std::string historySeconds(const Rational& q){Wide scaled=static_cast<Wide>(q.numerator())*1000000;auto den=static_cast<Wide>(q.denominator());Wide n=scaled/den,rem=scaled%den;if(rem*2>den||(rem*2==den&&n%2))++n;auto all=wide(n);if(all.size()<=6)all=std::string(7-all.size(),'0')+all;all.insert(all.size()-6,".");return all;}
std::string historyTempo(const Rational& q){
    auto n=static_cast<std::uint64_t>(q.numerator()),den=static_cast<std::uint64_t>(q.denominator());auto whole=n/den,rem=n%den;std::string integral=std::to_string(whole);if(!rem)return integral;
    auto reduced=den;while(reduced%2==0)reduced/=2;while(reduced%5==0)reduced/=5;
    auto digit=[&](){Wide next=static_cast<Wide>(rem)*10;char c=static_cast<char>('0'+next/den);rem=static_cast<std::uint64_t>(next%den);return c;};
    if(reduced==1){std::string out=integral+'.';while(rem)out.push_back(digit());return out;}
    std::string significant;int exponent;
    if(whole){significant=integral;exponent=static_cast<int>(integral.size())-1;}
    else{exponent=-1;char d=digit();while(d=='0'){--exponent;d=digit();}significant.push_back(d);}
    while(significant.size()<18)significant.push_back(digit());
    bool tail=rem!=0||significant.find_first_not_of('0',18)!=std::string::npos;char next=significant[17];significant.resize(17);
    if(next>'5'||(next=='5'&&(tail||(significant.back()-'0')%2))){std::size_t at=significant.size();while(at&&significant[at-1]=='9'){significant[--at]='0';}if(at)++significant[at-1];else{significant='1'+significant;++exponent;significant.resize(17);}}
    int position=exponent+1;std::string out;if(position<=0)out="0."+std::string(static_cast<std::size_t>(-position),'0')+significant;else if(position>=static_cast<int>(significant.size()))out=significant+std::string(static_cast<std::size_t>(position)-significant.size(),'0');else{out=significant;out.insert(static_cast<std::size_t>(position),".");}return out;
}
